                            <div style="color: 8e8e93; margintop: 5px;">14 napos ingyenes próba</div>
                        </div>

                        <ul style="liststyle: none; margin: 20px 0;">
                            <li style="margin: 12px 0; paddingleft: 25px; position: relative;">
                                <span style="position: absolute; left: 0; color: 34c759;">✓</span>
                                Korlátlan kérések
                            </li>
                            <li style="margin: 12px 0; paddingleft: 25px; position: relative;">
                                <span style="position: absolute; left: 0; color: 34c759;">✓</span>
                                Prioritás támogatás
                            </li>
                            <li style="margin: 12px 0; paddingleft: 25px; position: relative;">
                                <span style="position: absolute; left: 0; color: 34c759;">✓</span>
                                API hozzáférés
                            </li>
                            <li style="margin: 12px 0; paddingleft: 25px; position: relative;">
                                <span style="position: absolute; left: 0; color: 34c759;">✓</span>
                                Gyorsabb válaszok
                            </li>
                        </ul>

                        <button onclick="processPayment()" style="width: 100%; background: 007aff; color: white; padding: 15px; border: none; borderradius: 12px; fontsize: 16px; cursor: pointer; margintop: 20px;">Előfizetés indítása</button>
                    </div>
                ,
                about: 
                    <h2>Az AI Kereső</h2>
                    <p style="margin: 20px 0; lineheight: 1.6;">
                        Intelligens keresőmotor, amely ötvözi a modern AI technológiákat a magyar nyelvű tartalomkeresésben.
                    </p>
                    <h3>Hogyan működik?</h3>
                    <ul style="margin: 15px 0; lineheight: 1.8;">
                        <li>Ön feltesz egy kérdést természetes nyelven</li>
                        <li>Az AI optimalizálja a keresést a legjobb eredményekért</li>
                        <li>A rendszer begyűjti a releváns információkat</li>
                        <li>AIalapú válasz készül a megtalált forrásokból</li>
                    </ul>
                ,
                contact: 
                    <h2>Kapcsolatfelvétel</h2>
                    <div style="lineheight: 1.8; margin: 20px 0;">
                        <p><strong>AI Kereső Kft.</strong></p>
                        <p>📧 info@aikereso.hu</p>
                        <p>📞 +36 1 234 5678</p>
                        <p style="margintop: 20px; color: 8e8e93;">Válaszidő: 24 órán belül</p>
                    </div>
                ,
                login: 
                    <h2>Bejelentkezés</h2>
                    <form style="margin: 20px 0;">
                        <div style="marginbottom: 15px;">
                            <input type="email" placeholder="Email cím" style="width: 100%; padding: 12px; border: 2px solid 38383a; borderradius: 8px; background: 000; color: fff; fontsize: 16px;">
                        </div>
                        <div style="marginbottom: 20px;">
                            <input type="password" placeholder="Jelszó" style="width: 100%; padding: 12px; border: 2px solid 38383a; borderradius: 8px; background: 000; color: fff; fontsize: 16px;">
                        </div>
                        <button type="submit" style="width: 100%; background: 007aff; color: white; padding: 15px; border: none; borderradius: 8px; fontsize: 16px; cursor: pointer;">Bejelentkezés</button>
                    </form>

            };

            modalBody.innerHTML = content[type] || '<p>Tartalom nem található.</p>';
            document.getElementById('modal').classList.add('active');
        }

        function closeModal() {
            document.getElementById('modal').classList.remove('active');
        }

        function processPayment() {
            alert('Fizetési folyamat hamarosan elérhető!');
        }

        // Close modal on outside click
        window.addEventListener('click', function(e) {
            const modal = document.getElementById('modal');
